const b = $json.body || $json;
const jobId = String(b.jobId || '').trim();
const slug = String(b.slug || '').trim();
const checks = {
  nombre_correcto: !!b.nombre_correcto,
  categoria: !!b.categoria,
  horarios: !!b.horarios,
  telefono_wasap: !!b.telefono_wasap,
  fotos: !!b.fotos,
  link_web: !!b.link_web,
};
const done = Object.values(checks).filter(Boolean).length;
const total = Object.keys(checks).length;
const ok = done === total;
return [{ json: {
  ok: true,
  sistema: '07-presencia-digital',
  etapa: 'gbp',
  jobId,
  slug,
  checks,
  progreso: `${done}/${total}`,
  status: ok ? 'gbp_completo' : 'gbp_pendiente',
  todo: 'TODO: checklist manual o API GBP',
  at: new Date().toISOString()
}}];
